import{_ as i,o as t,c as a,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-tabellarisch-1.png",u="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-tabellarisch-2-stundentafel.png",p="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-tabellarisch-3-zuweisen.png",h="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-tabellarisch-4-kurs-anlegen.png",w=JSON.parse('{"title":"Fächer in einer Tabelle zuweisen und bearbeiten","description":"","frontmatter":{"title":"Fächer in einer Tabelle zuweisen und bearbeiten","source_pageid":805,"source_revision":5354},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/faecher-zuweisen-tabellarisch-gruppenprozesse-faecher.md","filePath":"schild3/suchen-gruppenprozesse/faecher-zuweisen-tabellarisch-gruppenprozesse-faecher.md"}'),d={name:"schild3/suchen-gruppenprozesse/faecher-zuweisen-tabellarisch-gruppenprozesse-faecher.md"};function o(c,r,g,b,m,f){return t(),a("div",null,[...r[0]||(r[0]=[s('<h1 id="facher-in-einer-tabelle-zuweisen-und-bearbeiten" tabindex="-1">Fächer in einer Tabelle zuweisen und bearbeiten <a class="header-anchor" href="#facher-in-einer-tabelle-zuweisen-und-bearbeiten" aria-label="Permalink to &quot;Fächer in einer Tabelle zuweisen und bearbeiten&quot;">​</a></h1><p>Die tabellarische Fachzuweisung bündelt Änderungen für eine Schülergruppe. Die folgenden Abschnitte trennen das Zuweisen und Bearbeiten vom Löschen bestehender Zuordnungen.</p><h2 id="zielgruppe-und-facherzuordnung-bearbeiten" tabindex="-1">Zielgruppe und Fächerzuordnung bearbeiten <a class="header-anchor" href="#zielgruppe-und-facherzuordnung-bearbeiten" aria-label="Permalink to &quot;Zielgruppe und Fächerzuordnung bearbeiten&quot;">​</a></h2><p>Bearbeiten Sie die Fächerzuordnung in einer Tabelle mit Schülern als Zeilen und Fächern als Spalten. Wählen Sie zuvor Zielgruppe, Lernabschnitt und die anzuzeigenden Fächer.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-tabellarisch-1.png"><img src="'+l+'" alt="Zuweisen von allen Fächern zu kompletten Klassen per Gruppenprozess." loading="lazy"></a></p><p><em>Zuweisen von allen Fächern zu kompletten Klassen per Gruppenprozess.</em></p><p>Der Gruppenprozess <strong>Fächer zuweisen (tabellarisch)</strong> soll die Unterrichtszuweisung bei Klassenunterricht erleichtern.</p><p>Dazu muss vorher im Container die Zielgruppe gefiltert werden, z.B. eine Klasse.</p><p>Der Gruppenprozess wird über <em>Gruppenprozesse ➜ Fächer ➜ Fächer zuweisen (tabellarisch)</em> gestartet.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-tabellarisch-2-stundentafel.png"><img src="'+u+'" alt="Auswahl einer passenden, zuvor definierten Stundentafel - oder Alle Fächer." loading="lazy"></a></p><p><em>Auswahl einer passenden, zuvor definierten Stundentafel - oder Alle Fächer.</em></p><p>Es erscheint ein Fenster, in dem ausgewählt werden kann, ob für die Zuweisung nur die Fächer</p><ul><li>eine <strong>Stundentafel</strong> oder über</li><li><strong>Alle Fächer</strong> alle verfügbaren Fächer</li></ul><p>zur Verfügung stehen sollen. Aus Gründen der Übersichtlichkeit wird zur Verwendung einer Stundentafel geraten.</p><p>Stundentafeln werden über <em>Kataloge ➜ Stundentafeln</em> definiert.</p><p>Sie können außerdem festlegen, ob Unterricht angezeigt wird, der bei den Schülerinnen und Schülern bereits als Kurs eingetragen ist.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-tabellarisch-3-zuweisen.png"><img src="'+p+`" alt="Zuweisen von Fächern und Kursen." loading="lazy"></a></p><p><em>Zuweisen von Fächern und Kursen.</em></p><p>Nun werden alle Schülerinnen und Schüler als Zeilen und alle Fächer als Spalten in einer Tabelle dargestellt.</p><p>Falls schon Belegungen vorhanden sind, werden diese mit aufgeführt.</p><p>In der obersten Zeile, im Screenshot blau markiert, wird nun gewählt, welches Fach mit welchen Informationen befüllt werden soll.</p><p>Als Standard-Bearbeitungsmodus ist oben rechts <strong>Zuweisen</strong> eingestellt.</p><p>Es steht weiterhin der Modus <strong>Löschen</strong> zur Verfügung, über den Zuweisungen entfernt werden können.</p><p>Zuerst ist im Kopfbereich des Fensters das <em>Unterrichtsfach</em> auswählen und die weiteren Eintragungen für <em>Kursart</em>, die <em>Lehrkraft</em> und die <em>Wochenzeiteinheiten</em> vornehmen.</p><p>Die Spalte des ausgewählten und damit zu bearbeitenden Faches wird nun in der Tabelle gelb hinterlegt.</p><p>Um das Fach mit den weiteren Angaben bei allen Schülern einzutragen, ist die <strong>Spaltenüberschrift</strong> anzuklicken. Die Daten werden nun ausgefüllt.</p><p>Soll ein Eintrag nur bei einzelnen Schülerinnen und Schülern erfolgen, so muss in die entsprechende <strong>Zelle</strong> der Tabelle geklickt werden.</p><p>Die Darstellung in den Fächerspalten erfolgt in der Art &quot;Kursart | Lehrkraft | Stundenzahl&quot;, also zum Beispiel</p><pre><code> &quot;PUK| ABCD | 2&quot;
</code></pre><p>Falls ein ebenfalls vorher definierter <em>Kurs</em> eingetragen ist, wird diese Anzeige mit der &quot; | Kursbez.&quot; ergänzt, also zum Beispiel</p><pre><code> &quot;| M - 10 E1&quot;
</code></pre><p>Sollte <em>Epochenunterricht</em> vorliegen, wird &quot; | E&quot; angehängt, um dies kenntlich zu machen.</p>`,32),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Im Screenshot ist zu sehen, dass Chemie mit einer Kursart "),e("em",null,"PUK"),n(", einer Lehrkraft und mit 2 WZE eingetragen ist. Mathematik ist gar nicht eingetragen und bei z.B. Physik fehlt noch die Lehrkraft. Keiner der Einträge hier wird im Kursunterricht unterrichtet.")])],-1),s('<p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-tabellarisch-4-kurs-anlegen.png"><img src="'+h+'" alt="Über das + einen Kurs definieren." loading="lazy"></a></p><p><em>Über das <strong>+</strong> einen Kurs definieren.</em></p><p>Sollte der Kurs noch nicht existieren, kann er über das <strong>+</strong> neben dem Dropdown-Menü <em>Kurs</em> definiert werden.</p><h2 id="loschen" tabindex="-1">Löschen <a class="header-anchor" href="#loschen" aria-label="Permalink to &quot;Löschen&quot;">​</a></h2><p>Wählen Sie für den Bearbeitungsmodus <strong>Löschen</strong> zuerst das betreffende <strong>Fach</strong> aus.</p><p>Danach bewirkt das <em>Anklicken der Spaltenüberschrift</em> beziehungsweise einer einzelnen <em>Zelle</em>, dass das ausgewählte Fach bei den Schülerinnen und Schülern gelöscht wird.</p><p>Haben Sie ihre Änderungen vorgenommen, klicken Sie links über der Tabelle auf <strong>In Leistungsdaten übernehmen</strong>. Andernfalls verlassen Sie den Gruppenprozess - und verwerfen eventuelle Änderungen - über einen Klick auf <strong>Schließen</strong>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=F%C3%A4cher_zuweisen_(tabellarisch)_(Gruppenprozesse_F%C3%A4cher)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5354.</p>',9)])])}const _=i(d,[["render",o]]);export{w as __pageData,_ as default};
